import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  // The e2e build bakes in a test NEXT_PUBLIC_WS_URL, so it gets its own
  // output directory rather than overwriting a normal build.
  distDir: process.env.NEXT_DIST_DIR ?? ".next",
  async headers() {
    return [
      {
        // Seed files are regenerated by `pnpm seed` and change rarely. They
        // are revalidated rather than cached as immutable because the file
        // names aren't content-hashed.
        source: "/seed/:file*",
        headers: [
          { key: "Content-Type", value: "application/octet-stream" },
          { key: "Cache-Control", value: "public, max-age=3600, stale-while-revalidate=86400" },
        ],
      },
    ];
  },
};

export default nextConfig;
